"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    by_id = {}
    for node in nodes:
        nid = node['id']
        if nid in by_id:
            raise ValueError(f'Duplicate node id {nid}')
        by_id[nid] = node
    children = {nid: [] for nid in by_id}
    root_id = None
    for node in nodes:
        pid = node['parent']
        if pid is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = node['id']
        else:
            if pid not in by_id:
                raise ValueError(f'Parent {pid} not found')
            children[pid].append(node['id'])
    if root_id is None:
        raise ValueError('No root node')
    removed = set()
    removal_order = []
    sorted_ids = sorted(by_id.keys(), key=lambda nid: (-by_id[nid]['depth'], nid))
    for nid in sorted_ids:
        node = by_id[nid]
        if nid == root_id:
            continue
        if node['symbol'] in required_symbols:
            continue
        if not node.get('removable', False):
            continue
        has_retained_child = any(cid not in removed for cid in children.get(nid, []))
        if has_retained_child:
            continue
        # node symbol is not required, so required symbols remain represented
        removed.add(nid)
        removal_order.append(nid)
    retained = sorted([nid for nid in by_id if nid not in removed])
    return {
        'removed_node_ids': removal_order,
        'retained_node_ids': retained
    }"
}
